                            try { Promise.resolve(r).then(function () { later(pass, 0); }, function () { later(pass, 0); }); } catch (e) {}
                            return r;
                        };
                    }
                } catch (e) {}
                return boot.apply(this, arguments);
            };
        }
    } catch (e) {}
    if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", function () { later(start, 0); }); }
    else { later(start, 0); }
    return { install: install, pass: pass, version: "1.3" };
})();


(function() {
    'use strict';

    class VariabilityLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Variability Lab - Serial Processor System';
            this.version = '1.2.0';
            this.CV_MAP = { low: 0.35, medium: 1.0, high: 2.0 };
            // The real line the design must be committed on (case and TN 9.1 Exhibit 4):
            // Stations 1 and 3 at their Low benchmark, Station 2 drifted, read at the harder (High) tier.
            // Variability cannot be bought down in 20 days at zero capex, so the grade tests buffer and CONWIP on this line.
            this.PLANT = { s1Var: 'low', s2Var: 'high', s3Var: 'low' };
            this.FLOOR_EFF = 85;    // 8.5 of the 10 units/min design rate
            this.CT_MAX = 18;
            this.WIP_MAX = 24;
            this.TIERS = [[88, 'flow_master'], [72, 'practitioner'], [55, 'analyst'], [0, 'explorer']];
        }

        _t(key, vars) {
            var s = null;
            try { if (window.mySimulation && window.mySimulation.t) s = window.mySimulation.t(key); } catch (e) {}
            if (s == null || s === key) {
                var tr = this.getTranslations();
                var tl = tr[this._lang()] || tr.en;
                s = (tl && tl[key] != null) ? tl[key] : (tr.en[key] != null ? tr.en[key] : key);
            }
            if (vars) Object.keys(vars).forEach(function (k) { s = String(s).split('{' + k + '}').join(vars[k]); });
            return s;
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = document.documentElement && document.documentElement.lang;
            return (h || 'en').slice(0, 2);
        }

        _fmt(x, dec) {
            var s = Number(x).toFixed(dec == null ? 1 : dec);
            return this._lang() === 'es' ? s.replace('.', ',') : s;
        }

        _plantCheck(d) {
            var sim = this._simulateSteadyState({
                s1Var: this.PLANT.s1Var, s2Var: this.PLANT.s2Var, s3Var: this.PLANT.s3Var,
                buffer: d.buffer, conwip: d.conwip, conwipLimit: d.conwipLimit
            });
            return {
                efficiency: sim.efficiency, wip: sim.wip, flowTime: sim.flowTime,
                floorMet: sim.efficiency >= this.FLOOR_EFF,
                ctMet: sim.flowTime < this.CT_MAX,
                wipMet: sim.wip <= this.WIP_MAX
            };
        }

        _clamp01(x) { return Math.max(0, Math.min(1, x)); }

        // Outcome (75): buffer and CONWIP of the latest run, tested on the real line.
        // Process (25): the diagnostic experiments of the TN protocol, read from the run list.
        _composite(runs) {
            if (!runs || !runs.length) return { overall: 0, outcome: 0, process: 0, parts: {} };
            var last = runs[runs.length - 1];
            var pc = this._plantCheck(last);
            var thPts = 25 * this._clamp01((pc.efficiency - 62) / 23) + (pc.floorMet ? 20 : 0);
            var leanPts = 15 * this._clamp01((14 - pc.flowTime) / 8.5);
            var bufPts = 15 * this._clamp01(1 - Math.max(0, last.buffer - 10) / 10);
            var outcome = thPts + leanPts + bufPts;
            var p = this._processFlags(runs);
            var process = (p.benchmark ? 4 : 0) + (p.isolated ? 4 : 0) + (p.bufferTest ? 6 : 0) + (p.capCompare ? 6 : 0) + (p.harder ? 5 : 0);
            var overall = Math.max(0, Math.min(100, Math.round((outcome + process) * 10) / 10));
            return { overall: overall, outcome: Math.round(outcome * 10) / 10, process: process, plant: pc, flags: p,
                     parts: { th: thPts, lean: leanPts, buf: bufPts } };
        }

        _processFlags(runs) {
            var code = function (r) { return r.s1Var + '-' + r.s2Var + '-' + r.s3Var; };
            var benchmark = runs.some(function (r) { return r.s1Var === 'low' && r.s2Var === 'low' && r.s3Var === 'low'; });
            var isolated = runs.some(function (r) { return r.s1Var === 'low' && r.s3Var === 'low' && r.s2Var !== 'low'; });
            var bufferTest = false, capCompare = false;
            for (var i = 0; i < runs.length; i++) {
                for (var j = i + 1; j < runs.length; j++) {
                    var a = runs[i], b = runs[j];
                    if (code(a) !== code(b)) continue;
                    if (a.conwip !== 'on' && b.conwip !== 'on' && a.buffer !== b.buffer) bufferTest = true;
                    if (a.conwip === 'on' && b.conwip === 'on' && a.buffer === b.buffer && a.conwipLimit !== b.conwipLimit) capCompare = true;
                }
            }
            var harder = runs.some(function (r) { return r.s2Var === 'high'; });
            return { benchmark: benchmark, isolated: isolated, bufferTest: bufferTest, capCompare: capCompare, harder: harder };
        }

        _tierOf(score) {
            for (var i = 0; i < this.TIERS.length; i++) if (score >= this.TIERS[i][0]) return this.TIERS[i][1];
            return 'explorer';
        }

        _runsFrom(history, upToPeriod) {
            var out = [];
            (history || []).forEach(function (h) {
                if (!h || !h.decisions) return;
                if (upToPeriod != null && h.period != null && h.period >= upToPeriod) return;
                var d = h.decisions;
                out.push({ period: h.period, s1Var: d.s1Var, s2Var: d.s2Var, s3Var: d.s3Var,
                           buffer: parseInt(d.buffer, 10) || 0, conwip: d.conwip, conwipLimit: parseInt(d.conwipLimit, 10) || 0,
                           efficiency: h.results ? h.results.efficiency : null });
            });
            return out;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    efficiencyHistory: [],
                    throughputHistory: [],
                    wipHistory: [],
                    flowTimeHistory: [],
                    configHistory: [],
                    bestEfficiency: 0,
                    experiments: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    s1Var: 'medium',
                    s2Var: 'medium',
                    s3Var: 'medium',
                    buffer: 3,
                    conwip: 'off',
                    conwipLimit: 6
                };
            }
        }

        validateDecisions(decisions) {
            const s1 = document.getElementById('s1VarInput');
            const s2 = document.getElementById('s2VarInput');
            const s3 = document.getElementById('s3VarInput');
            const bufferEl = document.getElementById('bufferInput');
            const conwipEl = document.getElementById('conwipInput');
            const conwipLimitEl = document.getElementById('conwipLimitInput');

            if (s1) decisions.s1Var = s1.value;
            if (s2) decisions.s2Var = s2.value;
            if (s3) decisions.s3Var = s3.value;
            if (bufferEl) decisions.buffer = parseInt(bufferEl.value, 10);
            if (conwipEl) decisions.conwip = conwipEl.value;
            if (conwipLimitEl) decisions.conwipLimit = parseInt(conwipLimitEl.value, 10);

            if (!['low', 'medium', 'high'].includes(decisions.s1Var) ||
                !['low', 'medium', 'high'].includes(decisions.s2Var) ||
                !['low', 'medium', 'high'].includes(decisions.s3Var)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('var_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.buffer) || decisions.buffer < 0 || decisions.buffer > 20) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('buffer_warning'), 'warning'
                );
                return false;
            }
            if (decisions.conwip === 'on') {
                if (isNaN(decisions.conwipLimit) || decisions.conwipLimit < 2 || decisions.conwipLimit > 20) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('conwip_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        _simulateSteadyState(d) {
            const cv1 = this.CV_MAP[d.s1Var];
            const cv2 = this.CV_MAP[d.s2Var];
            const cv3 = this.CV_MAP[d.s3Var];
            const cv1Sq = cv1 * cv1;
            const cv2Sq = cv2 * cv2;
            const cv3Sq = cv3 * cv3;

            // Position weights capture the Variability Interaction Law
            // (upstream variability propagates downstream more than the reverse)
            const posWeights = [1.00, 0.65, 0.30];
            const rawVarImpact = cv1Sq * posWeights[0] + cv2Sq * posWeights[1] + cv3Sq * posWeights[2];

            // Buffer mitigation - diminishing returns
            const buffer = d.buffer;
            const bufferMitigation = 1 - 0.22 * Math.sqrt(Math.min(buffer, 20));
            const effVar = rawVarImpact * Math.max(0.3, bufferMitigation);

            // Throughput efficiency relative to zero-variability max (1.0 unit / min)
            let efficiency = 100 / (1 + effVar * 0.22);

            // CONWIP effect on throughput
            let wipCappedByConwip = false;
            if (d.conwip === 'on') {
                const optimalConwip = 5;
                const cl = d.conwipLimit;
                if (cl < 3) {
                    efficiency *= 0.55;
                } else if (cl < 5) {
                    efficiency *= 0.82;
                } else if (cl <= 10) {
                    efficiency *= 1.03;
                } else {
                    efficiency *= 0.97;
                }
                wipCappedByConwip = true;
            }

            efficiency = Math.max(18, Math.min(98.5, efficiency));
            const throughput = efficiency / 100;

            // Natural WIP before CONWIP
            const avgBufferFillRatio = Math.min(0.9, 0.15 + effVar * 0.08);
            const avgBuf1 = buffer * avgBufferFillRatio;
            const avgBuf2 = buffer * avgBufferFillRatio * 0.9;
            let wip = 3 + avgBuf1 + avgBuf2;

            if (wipCappedByConwip) {
                wip = Math.min(wip, d.conwipLimit);
            }

            const flowTime = wip / throughput;
            const utilization = throughput;

            // Blocking / starvation frequencies
            const bufferFreeFactor = Math.max(0.2, 1 - buffer * 0.07);
            const block1 = Math.min(0.45, cv2Sq * 0.035 * bufferFreeFactor + cv3Sq * 0.015 * bufferFreeFactor);
            const block2 = Math.min(0.45, cv3Sq * 0.045 * bufferFreeFactor);
            const block3 = 0;
            const starv1 = 0;
            const starv2 = Math.min(0.45, cv1Sq * 0.040 * bufferFreeFactor);
            const starv3 = Math.min(0.45, cv1Sq * 0.025 * bufferFreeFactor + cv2Sq * 0.030 * bufferFreeFactor);

            const littleRatio = wip / (throughput * flowTime);

            return {
                throughput: throughput,
                efficiency: efficiency,
                wip: wip,
                flowTime: flowTime,
                littleRatio: littleRatio,
                util1: utilization, util2: utilization, util3: utilization,
                block1: block1, block2: block2, block3: block3,
                starv1: starv1, starv2: starv2, starv3: starv3,
                buffer1Occ: avgBuf1, buffer2Occ: avgBuf2,
                bufferCap: buffer,
                cv1: cv1, cv2: cv2, cv3: cv3,
                effectiveVariability: effVar
            };
        }

        calculateResults(state) {
            const d = state.decisions;
            const sim = this._simulateSteadyState(d);

            // Signature: e.g. M-M-M, buffer 3, CONWIP on 6
            const varCode = (d.s1Var[0] + '-' + d.s2Var[0] + '-' + d.s3Var[0]).toUpperCase();
            const conwipLabel = d.conwip === 'on' ? ('CONWIP ' + d.conwipLimit) : 'push';
            const configLabel = varCode + ' · buf ' + d.buffer + ' · ' + conwipLabel;

            // per-period values written by index, so an undone and resubmitted run replaces itself
            const ds = state.domainState;
            const idx = Math.max(0, (parseInt(state.currentPeriod, 10) || 1) - 1);
            ['efficiencyHistory', 'throughputHistory', 'wipHistory', 'flowTimeHistory', 'configHistory', 'plantEffHistory', 'scoreHistory'].forEach(function (k) {
                if (!Array.isArray(ds[k])) ds[k] = [];
                ds[k].length = Math.min(ds[k].length, idx);
            });
            ds.efficiencyHistory[idx] = sim.efficiency;
            ds.throughputHistory[idx] = sim.throughput;
            ds.wipHistory[idx] = sim.wip;
            ds.flowTimeHistory[idx] = sim.flowTime;
            ds.configHistory[idx] = configLabel;
            ds.experiments = idx + 1;
            ds.bestEfficiency = Math.max.apply(null, ds.efficiencyHistory.map(Number));

            // grade: buffer and CONWIP of the latest run, on the real line, plus the diagnostic protocol (one helper, _composite)
            const runs = this._runsFrom(state.history, state.currentPeriod);
            runs.push({ period: state.currentPeriod, s1Var: d.s1Var, s2Var: d.s2Var, s3Var: d.s3Var, buffer: d.buffer, conwip: d.conwip, conwipLimit: d.conwipLimit, efficiency: sim.efficiency });
            const comp = this._composite(runs);
            ds.plantEffHistory[idx] = comp.plant.efficiency;
            ds.scoreHistory[idx] = comp.overall;
            const tier = this._tierOf(comp.overall);
            ds.performance = Object.assign({}, ds.performance || {}, {
                overallScore: comp.overall, outcomeScore: comp.outcome, processScore: comp.process, tier: tier
            });
            ds.performanceTier = tier;
            ds.lastPlant = { efficiency: comp.plant.efficiency, wip: comp.plant.wip, flowTime: comp.plant.flowTime, floorMet: comp.plant.floorMet };

            // Update live station visuals (async so framework updates first)
            var self = this;
            setTimeout(function() { self._renderLine(sim, d); self._renderPlant(comp); }, 50);

            return {
                period: state.currentPeriod,
                config: configLabel,
                variabilityCode: varCode,
                throughput: sim.throughput,
                efficiency: sim.efficiency,
                wip: sim.wip,
                flowTime: sim.flowTime,
                littleRatio: sim.littleRatio,
                util1: sim.util1, util2: sim.util2, util3: sim.util3,
                block1: sim.block1, block2: sim.block2, block3: sim.block3,
                starv1: sim.starv1, starv2: sim.starv2, starv3: sim.starv3,
                buffer1Occ: sim.buffer1Occ,
                buffer2Occ: sim.buffer2Occ,
                bufferCap: sim.bufferCap,
                plantEfficiency: comp.plant.efficiency,
                plantWip: comp.plant.wip,
                plantFlowTime: comp.plant.flowTime,
                plantFloorMet: comp.plant.floorMet,
                outcomeScore: comp.outcome,
                processScore: comp.process,
                overallScore: comp.overall,
                score: comp.overall
            };
        }

        _renderLine(sim, d) {
            const pct = (x) => (x * 100).toFixed(1) + '%';
            const num = (x, dec) => Number(x).toFixed(dec == null ? 2 : dec);

