            setText('block1', pct(sim.block1));
            setText('block2', pct(sim.block2));
            setText('block3', pct(sim.block3));
            setText('starv1', pct(sim.starv1));
            setText('starv2', pct(sim.starv2));
            setText('starv3', pct(sim.starv3));
            setText('buffer1Cap', sim.bufferCap);
            setText('buffer2Cap', sim.bufferCap);
            setText('buffer1Occ', num(sim.buffer1Occ, 1));
            setText('buffer2Occ', num(sim.buffer2Occ, 1));

