            if (effEl) effEl.textContent = this._fmt(lp.efficiency, 1) + '%';
            if (stEl) {
                stEl.textContent = this._t(lp.floorMet ? 'plant_met' : 'plant_not_met', {
                    th: this._fmt(lp.efficiency / 10, 2), wip: this._fmt(lp.wip, 1), ct: this._fmt(lp.flowTime, 1)
                });
