                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 100,
                                title: { display: true, text: this._t('chart_th_series'), color: '#34d399' },
                                ticks: { color: '#94a3b8', callback: (v) => v + '%' },
                                grid: { color: 'rgba(148,163,184,0.12)' }
                            },
                            x: {
                                ticks: { color: '#94a3b8' },
                                grid: { color: 'rgba(148,163,184,0.08)' }
                            }
                        }
                    }
                },
                wipFlowChart: {
                    type: 'bar',
                    data: {
