        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const self = this;
            const effs = history.map(r => (r.results && r.results.efficiency) || 0);
            const throughputs = history.map(r => (r.results && r.results.throughput) || 0);
            const wips = history.map(r => (r.results && r.results.wip) || 0);
            const bestEff = Math.max.apply(null, effs);
            const worstEff = Math.min.apply(null, effs);
            const avgEff = effs.reduce((s, v) => s + v, 0) / effs.length;
            const avgTH = throughputs.reduce((s, v) => s + v, 0) / throughputs.length;
            const avgWIP = wips.reduce((s, v) => s + v, 0) / wips.length;

            const runs = this._runsFrom(history, null);
            const comp = this._composite(runs);
            const last = runs[runs.length - 1];
            const own = this._simulateSteadyState(last);
            const pc = comp.plant;
            const tier = this._tierOf(comp.overall);
            const f = (x, d) => self._fmt(x, d);
            const pcOf = runs.map(r => self._plantCheck(r));
            const simOf = runs.map(r => self._simulateSteadyState(r));

            // what the final commitment did, read from the run itself
            const keys = [];
            if (!pc.floorMet) {
                if (last.conwip !== 'on') keys.push('m_buffer_only');
                else if (last.conwipLimit < 5) keys.push('m_tight_cap');
                else if (last.conwipLimit === 12 && last.buffer === 5) keys.push('m_option_a');
                else if (last.conwipLimit > 10) keys.push('m_loose_cap');
                else keys.push('m_short_buffer');
                if (own.efficiency >= this.FLOOR_EFF && last.s2Var === 'medium') keys.push('m_medium_reading');
                if (own.efficiency >= this.FLOOR_EFF && last.s2Var === 'low') keys.push('m_assumed_away');
            }
            if (last.buffer > 10) keys.push('m_overbuffer');
            if (pc.floorMet && last.buffer <= 10) keys.push('ok_commit');
            const vars = { b: last.buffer, l: last.conwipLimit, eff: f(pc.efficiency, 1), own: f(own.efficiency, 1),
                           wip: f(pc.wip, 1), ct: f(pc.flowTime, 1), floor: this.FLOOR_EFF };
            const verdictLines = keys.map(k => self._t(k, vars));

            // turning point: the first run whose buffer and CONWIP held the floor on the real line
            let firstOk = -1, bestI = 0;
            pcOf.forEach((p, i) => { if (firstOk < 0 && p.floorMet) firstOk = i; if (p.efficiency > pcOf[bestI].efficiency) bestI = i; });
            let turning;
            if (firstOk >= 0 && pc.floorMet) turning = this._t('tp_found', { n: firstOk + 1, b: runs[firstOk].buffer, l: runs[firstOk].conwip === 'on' ? runs[firstOk].conwipLimit : '—', eff: f(pcOf[firstOk].efficiency, 1) });
            else if (firstOk >= 0) turning = this._t('tp_lost', { n: firstOk + 1, eff: f(pcOf[firstOk].efficiency, 1), last: runs.length, now: f(pc.efficiency, 1) });
            else turning = this._t('tp_never', { n: bestI + 1, eff: f(pcOf[bestI].efficiency, 1), floor: this.FLOOR_EFF });

            // insights from the run list
            const insights = [];
            const fl = comp.flags;
            if (fl.benchmark && fl.isolated) {
                const i = runs.findIndex(r => r.s1Var === 'low' && r.s2Var === 'low' && r.s3Var === 'low');
                const j = runs.findIndex(r => r.s1Var === 'low' && r.s3Var === 'low' && r.s2Var !== 'low');
                insights.push(this._t('in_isolated', { i: i + 1, j: j + 1, a: f(simOf[i].efficiency, 1), c: f(simOf[j].efficiency, 1), d: f(simOf[i].efficiency - simOf[j].efficiency, 1) }));
            } else insights.push(this._t('in_not_isolated'));
            let bp = null, cp = null;
            for (let i = 0; i < runs.length && (!bp || !cp); i++) for (let j = i + 1; j < runs.length; j++) {
                const A = runs[i], B = runs[j];
                if (A.s1Var + A.s2Var + A.s3Var !== B.s1Var + B.s2Var + B.s3Var) continue;
                if (!bp && A.conwip !== 'on' && B.conwip !== 'on' && A.buffer !== B.buffer) bp = [i, j];
                if (!cp && A.conwip === 'on' && B.conwip === 'on' && A.buffer === B.buffer && A.conwipLimit !== B.conwipLimit) cp = [i, j];
            }
            if (bp) insights.push(this._t('in_buffer', { b1: runs[bp[0]].buffer, b2: runs[bp[1]].buffer, e1: f(simOf[bp[0]].efficiency, 1), e2: f(simOf[bp[1]].efficiency, 1), w1: f(simOf[bp[0]].wip, 1), w2: f(simOf[bp[1]].wip, 1) }));
            else insights.push(this._t('in_no_buffer'));
            if (cp) insights.push(this._t('in_caps', { l1: runs[cp[0]].conwipLimit, l2: runs[cp[1]].conwipLimit, e1: f(simOf[cp[0]].efficiency, 1), e2: f(simOf[cp[1]].efficiency, 1), w1: f(simOf[cp[0]].wip, 1), w2: f(simOf[cp[1]].wip, 1) }));
            else insights.push(this._t('in_no_caps'));
            insights.push(this._t('in_little'));

            return {
                bestEfficiency: bestEff,
                worstEfficiency: worstEff,
                avgEfficiency: avgEff,
                avgThroughput: avgTH,
                avgWIP: avgWIP,
                efficiencySpread: bestEff - worstEff,
                totalPeriods: history.length,
                plantEfficiency: pc.efficiency,
                plantWip: pc.wip,
                plantFlowTime: pc.flowTime,
                plantFloorMet: pc.floorMet,
                commitBuffer: last.buffer,
                commitConwip: last.conwip === 'on' ? last.conwipLimit : 0,
                outcomeScore: comp.outcome,
                processScore: comp.process,
                composite: comp.overall,
                overallScore: comp.overall,
                totalScore: comp.overall,
                score: comp.overall,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._t('tier_' + tier),
                mistakeKeys: keys,
                verdictLines: verdictLines,
                turningPoint: turning,
                insights: insights,
                questions: [this._t('q1'), this._t('q2'), this._t('q3')]
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || typeof summary.overallScore !== 'number') return '';
            const esc = (x) => String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const f = (x, d) => this._fmt(x, d);
            const li = (arr) => (arr || []).map(x => '<li>' + esc(x) + '</li>').join('');
            const kpis = [
                [this._t('cm_plant_eff'), f(summary.plantEfficiency, 1) + '%'],
                [this._t('cm_plant_wip'), f(summary.plantWip, 1)],
                [this._t('cm_plant_ct'), f(summary.plantFlowTime, 1)],
                [this._t('cm_floor'), this._t(summary.plantFloorMet ? 'cm_yes' : 'cm_no')],
                [this._t('cm_commit'), this._t('cm_commit_val', { b: summary.commitBuffer, l: summary.commitConwip ? summary.commitConwip : this._t('cm_push') })]
            ];
            let h = '<div class="varlab-cm" role="region" aria-label="' + esc(this._t('cm_heading')) + '">';
            h += '<h3 class="varlab-cm-title">' + esc(this._t('cm_heading')) + '</h3>';
            h += '<p class="varlab-cm-score"><strong>' + esc(f(summary.overallScore, 1)) + '/100</strong> &middot; ' + esc(summary.performanceLabel) + '</p>';
            h += '<p class="varlab-cm-sub">' + esc(this._t('cm_subscores', { o: f(summary.outcomeScore, 1), p: summary.processScore })) + '</p>';
            h += '<ul class="varlab-cm-kpis">' + kpis.map(k => '<li><span>' + esc(k[0]) + '</span><b>' + esc(k[1]) + '</b></li>').join('') + '</ul>';
            h += '<h4>' + esc(this._t('cm_verdict')) + '</h4><ul class="varlab-cm-verdict">' + li(summary.verdictLines) + '</ul>';
            h += '<h4>' + esc(this._t('cm_turning')) + '</h4><p>' + esc(summary.turningPoint) + '</p>';
            h += '<h4>' + esc(this._t('cm_insights')) + '</h4><ul>' + li(summary.insights) + '</ul>';
            h += '<h4>' + esc(this._t('cm_questions')) + '</h4><ol>' + li(summary.questions) + '</ol>';
            h += '</div>';
            return h;
        }

